const assert = require('node:assert/strict');

const { renderInvoice } = require('../.build/invoice');
const { renderReport } = require('../.build/report');
const { formatAmount } = require('../.build/money');

assert.equal(renderInvoice('inv', 123), 'inv: $1.23');
assert.equal(renderReport([{ id: 'a', cents: 0 }, { id: 'b', cents: -1 }]), 'a,0.00\nb,-0.01');

// formatAmount: sign + absolute whole units + exactly two fraction digits, no symbol.
assert.equal(formatAmount(123), '1.23');
assert.equal(formatAmount(0), '0.00');
assert.equal(formatAmount(-1), '-0.01');
assert.equal(formatAmount(5), '0.05');
assert.equal(formatAmount(100), '1.00');
assert.equal(formatAmount(-100), '-1.00');
assert.equal(formatAmount(-12345), '-123.45');

// renderers preserve exact output for positive, zero and negative cents.
assert.equal(renderInvoice('x', 0), 'x: $0.00');
assert.equal(renderInvoice('x', -1), 'x: $-0.01');
assert.equal(renderInvoice('x', 123456), 'x: $1234.56');
assert.equal(renderReport([]), '');
assert.equal(renderReport([{ id: 'p', cents: 7 }, { id: 'z', cents: 0 }, { id: 'n', cents: -7 }]), 'p,0.07\nz,0.00\nn,-0.07');

